const MEALS=[
{id:'biryani',name:'برياني دجاج',cat:'دجاج',price:4.5,serves:1,desc:'أرز برياني، دجاج متبّل، خضار وصوص جانبي.',img:'meal-chicken.webp',allergens:['حليب']},
{id:'burger',name:'برغر دجاج',cat:'دجاج',price:4.5,serves:1,desc:'دجاج مشوي، خبز برغر، خضار طازجة.',img:'meal-balanced.webp',allergens:['غلوتين']},
{id:'stroganoff',name:'استراغنوف دجاج',cat:'دجاج',price:4.5,serves:1,desc:'شرائح دجاج مع صوص كريمي وأرز.',img:'meal-chicken.webp',allergens:['حليب']},
{id:'sayadia',name:'صيادية',cat:'سمك',price:4.5,serves:1,desc:'سمك مطهو مع أرز متبل وخضار.',img:'',allergens:['سمك']},
{id:'lemonfish',name:'سمك بالليمون والأعشاب',cat:'سمك',price:4.5,serves:1,desc:'سمك بالليمون والأعشاب مع خضار موسمية.',img:'',allergens:['سمك']},
{id:'burrito',name:'بوريتو بول (لحمة)',cat:'لحوم',price:5,serves:1,desc:'لحم، أرز، خضار وصوص خاص.',img:'',allergens:[]},
{id:'beefpotato',name:'يخنة بطاطا باللحمة',cat:'لحوم',price:5,serves:1,desc:'قطع لحمة مع البطاطا والخضار.',img:'',allergens:[]},
{id:'quinoa',name:'تبولة الكينوا',cat:'نباتي',price:2.5,serves:1,desc:'كينوا وخضار طازجة مع الليمون.',img:'',allergens:[]},
{id:'greek',name:'سلطة يونانية',cat:'سلطات',price:3.5,serves:1,desc:'خضار طازجة وجبنة فيتا وزيت زيتون.',img:'',allergens:['حليب']},
{id:'italian',name:'السلطة الإيطالية',cat:'سلطات',price:2,serves:1,desc:'مزيج خضار طازجة وتتبيلة إيطالية.',img:'',allergens:[]},
{id:'salmon',name:'سالمون',cat:'سمك',price:7,serves:1,desc:'سالمون وخضار مع صوص جانبي.',img:'',allergens:['سمك']},
{id:'shrimp',name:'جمبري',cat:'سمك',price:6,serves:1,desc:'جمبري مطهو مع أرز وخضار.',img:'',allergens:['قشريات']},
{id:'omelet',name:'أومليت بالجبن',cat:'فطور',price:2.75,serves:1,desc:'بيض وجبنة طازجة.',img:'',allergens:['بيض','حليب']},
{id:'hummus',name:'حمص باللحمة',cat:'فطور',price:3.75,serves:1,desc:'حمص طازج مع قطع اللحمة.',img:'',allergens:['سمسم']},
{id:'turkey',name:'ساندويش اللحوم الباردة',cat:'فطور',price:2.75,serves:1,desc:'خبز وخضار وشرائح لحوم باردة.',img:'',allergens:['غلوتين']}
];
MEALS.push({id:'whitepasta',name:'معكرونة وايت صوص',cat:'دجاج',price:4.5,serves:1,desc:'معكرونة بصلصة بيضاء كريمية مع الدجاج.',img:'white-pasta-home.jpg',allergens:['غلوتين','حليب']});
const HOME_MEAL_IDS=['beefpotato','whitepasta','biryani','sayadia'];
const MENU_LIST_IDS=['biryani','burger','stroganoff','sayadia','lemonfish','burrito','beefpotato','greek','quinoa'];
const PLANS=[{id:'trial',name:'تجربة المطعم',price:13,count:3,kind:'تجربة',features:['3 وجبات','اختيار الوجبات','تغيير موعد الاستلام']},{id:'chicken',name:'باقة الدجاج',price:79,count:20,kind:'شهري',features:['20 وجبة دجاج','اختيار الوجبات أسبوعياً','إمكانية التغيير أو التأجيل','التوصيل حسب المنطقة']},{id:'mixed',name:'الباقة المتنوعة',price:99,count:20,kind:'شهري',features:['20 وجبة دجاج ولحمة وسمك','اختيار الوجبات أسبوعياً','إمكانية التغيير أو التأجيل','التوصيل حسب المنطقة']}];
const GOVERNORATES=['عمّان','إربد','الزرقاء','البلقاء','مادبا','الكرك','معان','الطفيلة','جرش','عجلون','المفرق','العقبة'];
const ZONES=['العبدلي','الشميساني','الصويفية','عبدون','خلدا','تلاع العلي','دابوق','ناعور','الجبيهة','شارع المدينة المنورة','مرج الحمام','ماركا','جبل عمّان','الجاردنز','المدينة الرياضية'];
const adminSections=['الرئيسية','الطلبات','الاشتراكات','المنيو','العملاء','الشكاوى','المالية','الصلاحيات'];
const def={route:'home',drawer:false,modal:null,toast:'',user:null,staff:null,cart:[],plan:null,gov:'',zone:'',district:'',week:0,schedule:Array(20).fill(''),category:'الكل',allergy:'',search:'',method:'',authContext:'subscription',ref:'93K-2026-0001',details:{name:'',phone:'',address:'',email:'',note:''},orders:[],subscriptions:[],adminSection:'الرئيسية',adminSearch:'',adminFilter:'',editRecord:null,feedback:[],staffEntries:[]};
let saved={};try{saved=JSON.parse(localStorage.getItem('kitchen93-v1')||'{}')}catch(_){ }
let state={...def,...saved,drawer:false,modal:null,toast:'',schedule:Array.isArray(saved.schedule)?saved.schedule:def.schedule,adminViewAll:false,adminMode:saved.adminMode||'يومي',adminDay:saved.adminDay||'الأحد',adminPermissions:saved.adminPermissions||{}};
let popTimer;
const store=()=>{try{localStorage.setItem('kitchen93-v1',JSON.stringify({...state,drawer:false,modal:null,toast:''}))}catch(_){}};
const fmt=n=>Number(n).toFixed(2)+' JD',m=id=>MEALS.find(x=>x.id===id),plan=()=>PLANS.find(x=>x.id===state.plan)||PLANS[2];
const act=(label,action,style='secondary',attr='')=>`<button class="btn btn-${style}" data-action="${esc(action)}" ${attr}>${label}</button>`;
const opts=(xs,val='',label='اختر',allowEmpty=true)=>`${allowEmpty?`<option value="">${esc(label)}</option>`:''}${xs.map(x=>`<option value="${esc(x)}" ${x===val?'selected':''}>${esc(x)}</option>`).join('')}`;
const field=(name,label,type='text',required=false,value='',placeholder='')=>`<div class="field"><label for="${esc(name)}">${label}${required?' *':''}</label><input id="${esc(name)}" name="${esc(name)}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${required?'required':''} autocomplete="off"></div>`;
const areaField=(gov=state.gov,zone=state.zone)=>`<div class="field map-label"><label for="governorate">المحافظة</label><select id="governorate" data-change="governorate">${opts(GOVERNORATES,gov,'حدد المحافظة')}</select></div><div class="field map-label"><label for="zone">المنطقة</label><select id="zone" data-change="zone" ${gov==='عمّان'?'':'disabled'}>${opts(gov==='عمّان'?ZONES:[],zone,gov==='عمّان'?'اختر المنطقة':'اختر عمّان أولاً')}</select></div>`;
function header(){return `<header class="nav"><div class="nav-side"><button class="icon-btn" data-action="drawer" aria-label="فتح القائمة">${icon('menu')}</button></div><a class="brand" href="#/home" aria-label="93 Kitchen الرئيسية"><img src="assets/logo.svg" alt="93 Kitchen"></a><div class="nav-side left"><button class="icon-btn cart-anchor" data-action="cart" aria-label="السلة">${icon('cart')}${state.cart.length?`<span class="cart-counter">${state.cart.reduce((s,x)=>s+x.qty,0)}</span>`:''}</button><button class="icon-btn" data-action="account" aria-label="حسابي">${icon('user')}</button><span class="profile-greet ${state.user?'shown':''}">${state.user?`أهلاً ${esc(state.user.name.split(' ')[0])}`:''}</span></div></header>`;}
function drawer(){if(!state.drawer)return '';return `<div class="drawer-scrim" data-action="drawer"></div><aside class="drawer" aria-label="القائمة الجانبية"><div class="drawer-header"><img src="assets/logo.svg" alt="93 Kitchen"><button class="icon-btn" data-action="drawer" aria-label="إغلاق">${icon('close')}</button></div><nav class="drawer-links">${[['الرئيسية','home'],['قائمة الطعام','menu'],['الاشتراكات','plans'],['عن مطبخنا','home:about'],['اتصل بنا','home:footer'],[state.user?'اشتراكي':'تسجيل الدخول','account']].map(([l,to])=>`<button data-action="navigate:${to}">${l}</button>`).join('')}</nav><div class="drawer-bottom"><div class="footer-social"><a href="https://www.instagram.com/93kitchen.jo/" target="_blank" rel="noopener">Instagram</a><a href="https://www.facebook.com/" target="_blank" rel="noopener">Facebook</a><a href="https://wa.me/" target="_blank" rel="noopener">WhatsApp</a></div><p class="muted">الأردن · عمّان · ناعور</p><button class="btn btn-secondary" data-action="navigate:staff-login">بوابة الموظفين</button></div></aside>`;}
const MENU_ATLAS={burger:[1,0],stroganoff:[2,0],sayadia:[0,1],lemonfish:[1,1],burrito:[2,1],beefpotato:[0,2],greek:[1,2],quinoa:[2,2]};
function pic(x){
  const asset=x.id==='biryani'?'biryani-original.jpg':x.id==='whitepasta'?'white-pasta-home.jpg':state.route==='home'&&x.id==='sayadia'?'sayadia-home.jpg':state.route==='home'&&x.id==='beefpotato'?'beef-potato-home.jpg':null;
  if(asset)return '<img class="meal-photo" src="assets/'+asset+'" alt="'+esc(x.name)+'" loading="lazy" decoding="async">';
  const tile=MENU_ATLAS[x.id];
  if(tile)return '<div class="meal-photo meal-atlas atlas-x'+tile[0]+' atlas-y'+tile[1]+'" role="img" aria-label="'+esc(x.name)+'"></div>';
  return '<div class="meal-photo meal-fallback" role="img" aria-label="'+esc(x.name)+'"></div>';
}
function mealCard(x){return `<article class="meal-card">${pic(x)}<div class="meal-content"><h3>${esc(x.name)}</h3><div class="meal-meta"><span>تكفي ${x.serves===1?'شخصاً واحداً':x.serves+' أشخاص'}</span><span>• ${esc(x.cat)}</span></div><p class="meal-desc">${esc(x.desc)}</p><div class="meal-bottom"><span class="price">${fmt(x.price)}</span><span style="display:flex;gap:7px">${act('اطلب الوجبة','buy:'+x.id,'secondary',`aria-label="اطلب ${esc(x.name)}"`)}<button class="icon-btn cart-add" data-action="add:${x.id}" aria-label="أضف ${esc(x.name)} للسلة">${icon('plus')}</button></span></div></div></article>`;}
function planCard(x){return `<article class="plan-card ${state.plan===x.id?'selected':''}"><span class="badge">${esc(x.kind)}</span><h3 class="plan-title">${esc(x.name)}</h3><div class="plan-price">${x.price} <small>دينار</small></div><div class="muted">${x.count} وجبة</div><ul class="plan-features">${x.features.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><div class="plan-bottom">${act('اختر الاشتراك','plan:'+x.id,'secondary','btn-full')}</div></article>`;}
function sectionTitle(t,sub='',link=''){return `<div class="section-head"><h2>${t}</h2>${sub?`<p>${sub}</p>`:''}${link?`<button class="section-side-link" style="border:0;background:none" data-action="${link}">${t==='منيو اليوم'?'المنيو الكامل ←':'عرض الكل ←'}</button>`:''}</div>`;}
function footer(){return `<footer class="footer" id="footer"><div class="shell footer-grid"><div><img class="footer-logo" src="assets/logo.svg" alt="93 Kitchen"><p style="line-height:2">طازج · متوازن · صحي</p></div><div><h3>روابط سريعة</h3><button data-action="navigate:menu">الوجبات</button><button data-action="navigate:plans">الاشتراكات</button><button data-action="location-open">مناطق التوصيل</button><button data-action="navigate:payment">طرق الدفع</button></div><div><h3>معلومات</h3><button data-action="navigate:terms">سياسة الاشتراك</button><button data-action="navigate:home:about">عن مطبخنا</button><button data-action="navigate:terms">الشروط</button><button data-action="navigate:home:footer">اتصل بنا</button></div><div><h3>موقعنا</h3><div style="display:flex;align-items:center;gap:6px">${icon('pin')} الأردن · عمّان · ناعور</div><h3 style="margin-top:24px">تابعنا</h3><div class="footer-social"><a href="https://www.instagram.com/93kitchen.jo/" rel="noopener" target="_blank">Instagram</a><a href="https://www.facebook.com/" rel="noopener" target="_blank">Facebook</a><a href="https://wa.me/" rel="noopener" target="_blank">WhatsApp</a></div></div></div><div class="footer-bottom">© 93 Kitchen</div></footer>`;}
function homepage(){return `${header()}<main><section class="hero"><img class="hero-img" src="assets/hero.png" alt="طبق دجاج وأرز وخضروات طازجة"><h1>طازج. متوازن. صحي.</h1><p>وجبات بيتية طازجة ومتوازنة، جاهزة لدوامك ويومك.</p><div class="hero-actions">${act('استكشف الاشتراكات','navigate:plans','light','class="btn btn-light btn-lg"')}${act('اطلب وجبة اليوم','navigate:menu','primary','class="btn btn-primary btn-lg"')}</div></section><section class="section shell home-menu">${sectionTitle('منيو اليوم','','navigate:menu')}<div class="cards">${HOME_MEAL_IDS.map(id=>MEALS.find(x=>x.id===id)).filter(Boolean).map(mealCard).join('')}</div></section><section class="section shell home-plans">${sectionTitle('الاشتراكات الشهرية')}<div class="plan-grid">${PLANS.map(planCard).join('')}</div></section><section class="section shell home-delivery" id="delivery"><div class="delivery-box"><div><h2>التوصيل لمنطقتك</h2><p class="muted">اختار موقعك وتأكد إذا منطقتك مشمولة بالتوصيل.</p></div><div class="control-row">${'<div class="field map-label"><label for="homezone">منطقة التوصيل</label><select id="homezone" data-change="homezone">'+opts(ZONES,state.zone,'اختر منطقتك')+'</select></div>'}${act('تحقّق','home-check','secondary')}</div></div></section><section class="section home-about" id="about"><div class="about"><div class="about-text"><h2>عن مطبخنا</h2><p>في 93 Kitchen بنحضّر وجبات طازجة ومتوازنة بطابع الأكل البيتي، لتكون وجبتك اليومية أسهل.</p>${act('عن مطبخنا','navigate:about','secondary')}</div><img class="about-image" src="assets/chef.webp" alt="فريق المطبخ أثناء إعداد الوجبات"></div></section><section class="section shell home-reviews">${sectionTitle('آراء الناس وتجاربهم')}<div class="reviews">${[['سارة','الأكل مرتب وطعمه بيتي. الاشتراك سهّل عليّ وجبات الدوام.'],['أحمد','الوجبات مشبعة والخيارات متنوعة.'],['لينا','بحب إني أقدر أرتب وجبات الأسبوع من قبل.']].map(([name,feedback])=>`<div class="review-card"><div class="review-person"><img class="avatar" src="assets/review-${name==='سارة'?'sara':name==='أحمد'?'ahmad':'lina'}.png" alt=""><div><b>${name}</b><div class="stars">★★★★★</div></div></div><p class="muted">${feedback}</p></div>`).join('')}</div></section><section class="section shell home-faq">${sectionTitle('الأسئلة الشائعة')}<div class="faq"><details><summary>كيف بقدر أختار وجبات اشتراكي؟</summary><p>بعد تحديد المنطقة، اختار وجباتك لكل أسبوع واحفظ الجدول ثم راجع ملخص الاشتراك.</p></details><details><summary>هل بقدر أغير الوجبة أو أجلها؟</summary><p>يمكن طلب تعديل أو تأجيل الوجبات بحسب شروط وموعد التعديل المعتمد.</p></details><details><summary>هل التوصيل متاح لكل المحافظات؟</summary><p>تقدر تحدد محافظتك ومنطقتك للتحقق من التغطية. التوفر النهائي يؤكده المطعم قبل إكمال الطلب.</p></details><details><summary>متى يبدأ الاشتراك؟</summary><p>يبدأ بعد تأكيد استلام قيمة الاشتراك.</p></details></div></section></main>${footer()}`;}
function pageWrap(title,sub,html,back='home'){return `${header()}<main class="page page-${state.route}"><div class="shell"><button class="back" data-action="back:${back}">${icon('back')} رجوع</button><h1 class="page-title">${esc(title)}</h1>${sub?`<p class="page-subtitle">${sub}</p>`:''}${html}</div></main>${footer()}`;}
function menuPage(){const cats=['الكل','دجاج','سمك','لحوم','نباتي','سلطات'];let meals=MEALS.filter(x=>MENU_LIST_IDS.includes(x.id)).sort((a,b)=>MENU_LIST_IDS.indexOf(a.id)-MENU_LIST_IDS.indexOf(b.id)).filter(x=>(state.category==='الكل'||x.cat===state.category)&&(!state.allergy||!x.allergens.includes(state.allergy))&&(x.name.includes(state.search.trim())||x.desc.includes(state.search.trim())));return pageWrap('قائمة الطعام اليوم','اختار وجبتك، والباقي علينا.',`<div class="tabs">${cats.map(c=>`<button class="tab ${state.category===c?'active':''}" data-action="category:${c}">${c}</button>`).join('')}</div><div class="filter-bar"><div class="field"><label for="mealSearch">ابحث عن وجبة</label><input id="mealSearch" data-change="search" value="${esc(state.search)}" placeholder="اسم الوجبة"></div><div class="field"><label for="allergy">تجنب مكونات الحساسية</label><select id="allergy" data-change="allergy">${opts(['غلوتين','حليب','بيض','سمك','قشريات','سمسم'],state.allergy,'بدون استبعاد')}</select></div></div>${meals.length?`<div class="cards">${meals.map(mealCard).join('')}</div>`:'<div class="surface empty">ما في وجبات مطابقة للبحث الحالي. جرّب فلتر آخر.</div>'}`,'home');}
function plansPage(){return pageWrap('الاشتراكات','اختر الباقة المناسبة إلك، وبعدين رتب وجباتك بنفسك.',`<div class="plan-grid">${PLANS.map(planCard).join('')}</div>`,'home');}
function cartPage(){const sum=state.cart.reduce((n,x)=>n+(m(x.id)?.price||0)*x.qty,0);return pageWrap('السلة','راجع الوجبات قبل إتمام الطلب.',`<div class="split"><div class="panel"><h3>وجباتك</h3>${state.cart.length?state.cart.map(x=>`<div class="sum-row"><span><b>${esc(m(x.id)?.name||'وجبة')}</b><span class="muted"> × ${x.qty}</span></span><span>${fmt(m(x.id)?.price*x.qty)}</span><button class="icon-btn" data-action="remove:${x.id}" aria-label="حذف">${icon('close')}</button></div>`).join(''):'<div class="empty">السلة فارغة</div>'}<div style="margin-top:18px">${act('تصفح الوجبات','navigate:menu','secondary')}</div></div><div class="panel"><h3>ملخص الطلب</h3><div class="sum-row"><span>الوجبات</span><b>${state.cart.reduce((n,x)=>n+x.qty,0)}</b></div><div class="sum-row"><span>الإجمالي</span><span class="sum-total">${fmt(sum)}</span></div><p class="muted">رسوم التوصيل تُحدّد بعد اختيار المنطقة.</p>${act('متابعة الطلب','checkout-start','primary','class="btn btn-primary btn-full" '+(!state.cart.length?'disabled':''))}</div></div>`,'menu');}
function planner(){if(!state.plan)return plansPage();const p=plan(),num=p.count===3?3:20,base=state.week*5,days=['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس'];let selected=state.schedule.slice(0,num).filter(Boolean).length;const eligible=p.id==='chicken'?MEALS.filter(m=>m.cat==='دجاج'):MEALS.filter(m=>!['فطور','سلطات'].includes(m.cat));const daysThisWeek=p.count===3?3:5;let content=`<div class="stepper"><span class="step on">1 · تحديد المنطقة</span><span class="step on">2 · اختيار الوجبات</span><span class="step">3 · بياناتك</span><span class="step">4 · الدفع</span></div><div class="split"><div class="stack"><div class="panel"><div class="week-status"><h3 style="margin:0">جدول وجباتك</h3><span class="badge">${selected} / ${num} وجبة</span></div><div class="tabs">${Array.from({length:Math.ceil(num/5)},(_,i)=>`<button class="tab ${state.week===i?'active':''}" data-action="week:${i}">الأسبوع ${['الأول','الثاني','الثالث','الرابع'][i]}</button>`).join('')}</div><div class="day-grid">${days.slice(0,daysThisWeek).map((day,i)=>{const idx=base+i,value=state.schedule[idx];return `<div class="day-row ${value?'chosen':''}"><div><b>${day}</b><div class="muted">اليوم ${idx+1}</div></div><div class="field"><label>الوجبة</label><select data-change="mealday" data-index="${idx}"><option value="">اختار وجبتك</option>${eligible.map(x=>`<option value="${x.id}" ${value===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><span class="${value?'chosen-text':'muted'}">${value?icon('check')+' تم الاختيار':'بانتظار الاختيار'}</span></div>`}).join('')}</div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:20px">${act('حفظ الأسبوع','save-week','primary')}${state.week>0?act('الأسبوع السابق','week-prev','secondary'):''}${state.week<Math.ceil(num/5)-1?act('التالي','week-next','secondary'):''}</div></div></div><div class="stack"><div class="panel"><h3>اشتراكك</h3><div class="sum-row"><span>الباقة</span><b>${esc(p.name)}</b></div><div class="sum-row"><span>الوجبات</span><b>${num}</b></div><div class="sum-row"><span>التوصيل</span><span>${icon('pin')} ${esc(state.zone||state.gov||'لم تحدد')}</span></div><div class="sum-row"><span>الإجمالي</span><b class="sum-total">${fmt(p.price)}</b></div><button class="btn btn-secondary btn-full" style="margin-top:15px" data-action="location-open">تغيير موقع التوصيل</button></div><div class="panel"><b>المرونة في الاشتراك</b><p class="muted">تقدر تراجع الوجبات وتطلب تغييرها أو تأجيلها حسب سياسة المطعم.</p>${act('متابعة إلى بياناتك','subscription-next','primary','class="btn btn-primary btn-full"')}</div></div></div>`;return pageWrap('رتّب وجبات اشتراكك',`حدد وجبة لكل يوم من ${p.count===3?'أيام تجربة المطعم':'الأسابيع الأربعة'}.`,content,'plans');}
function authChoice(){let dest=state.authContext==='subscription'?'review':'payment';return pageWrap('كيف بدك تكمل؟','بإمكانك تسجيل الدخول أو إتمام الطلب كضيف.',`<div class="login-card stack"><div class="panel"><h3>عندي حساب</h3><p class="muted">سجّل دخولك للوصول لبياناتك المحفوظة.</p>${act('تسجيل الدخول','navigate:login','secondary','class="btn btn-secondary btn-full"')}</div><div class="panel"><h3>أكمل كضيف</h3><p class="muted">أضف اسمك ورقم هاتفك ومعلومات التوصيل.</p>${act('المتابعة كضيف','continue-guest','primary','class="btn btn-primary btn-full"')}</div><p class="center muted">ما عندك حساب؟ <button class="back" data-action="navigate:signup">إنشاء حساب</button></p></div>`,state.authContext==='subscription'?'planner':'cart');}
function authPage(signup=false){return pageWrap(signup?'إنشاء حساب':'تسجيل الدخول',signup?'أنشئ حسابك لتتابع وجباتك واشتراكاتك.':'أهلاً فيك من جديد.',`<form class="panel login-card" id="authForm"><div class="stack">${signup?field('fullName','الاسم الكامل','text',true,'','الاسم الكامل'):''}${field('authEmail','البريد الإلكتروني','email',true,'','example@email.com')}${field('authPass','كلمة المرور','password',true,'','كلمة المرور')}${act(signup?'إنشاء حساب':'تسجيل الدخول','submit-auth','primary','type="submit" class="btn btn-primary btn-full"')}</div><div class="divider">أو المتابعة باستخدام</div><div class="auth-providers"><button class="btn btn-secondary" data-action="provider:Google" type="button">Google</button><button class="btn btn-secondary" data-action="provider:Facebook" type="button">Facebook</button><button class="btn btn-secondary" data-action="provider:Apple" type="button">Apple</button></div><p class="center muted">${signup?'عندك حساب؟':'ما عندك حساب؟'} <button type="button" class="back" data-action="navigate:${signup?'login':'signup'}">${signup?'تسجيل الدخول':'إنشاء حساب'}</button></p></form>`,'identity');}
function customerDetails(){const d={...state.details};if(state.user){d.name=d.name||state.user.name;d.email=d.email||state.user.email;}const page=state.authContext==='subscription'?'الاشتراك':'الطلب';return pageWrap('بيانات التوصيل',`أدخل معلوماتك لإكمال ${page}.`,`<form id="detailsForm" class="panel narrow"><div class="form-grid">${field('name','الاسم الكامل','text',true,d.name)}${field('phone','رقم الهاتف','tel',true,d.phone)}${field('email','البريد الإلكتروني (اختياري)','email',false,d.email)}${'<div class="field map-label"><label for="detailsZone">منطقة التوصيل *</label><select id="detailsZone" name="detailsZone" required>'+opts(ZONES,state.zone,'حدد المنطقة')+'</select></div>'}</div><div style="height:16px"></div>${field('address','العنوان التفصيلي','text',true,d.address,'الشارع، المبنى، رقم الطابق')}<div style="height:14px"></div><div class="field"><label for="note">ملاحظات التوصيل (اختياري)</label><textarea name="note" id="note">${esc(d.note)}</textarea></div><div class="modal-actions">${act('رجوع','back:identity','secondary')}${act('متابعة','submit-details','primary','type="submit"')}</div></form>`,'identity');}
function subscriptionReview(){const p=plan(),num=p.count,choices=state.schedule.slice(0,num).map((id,i)=>({i,id})).filter(x=>x.id);return pageWrap('مراجعة الاشتراك','تأكد من اختياراتك قبل تأكيد طريقة الدفع.',`<div class="split"><div class="panel"><h3>الوجبات المختارة</h3>${choices.map(x=>`<div class="sum-row"><span>${x.i+1}. ${esc(m(x.id)?.name||'')}</span><span class="muted">الأسبوع ${Math.floor(x.i/5)+1}</span></div>`).join('')||'<p>لم يتم اختيار الوجبات</p>'}<div style="margin-top:17px">${act('تعديل جدول الوجبات','navigate:planner','secondary')}</div></div><div class="stack"><div class="panel"><h3>ملخص الاشتراك</h3><div class="sum-row"><span>الباقة</span><b>${esc(p.name)}</b></div><div class="sum-row"><span>الوجبات</span><b>${num}</b></div><div class="sum-row"><span>العميل</span><b>${esc(state.details.name)}</b></div><div class="sum-row"><span>المنطقة</span><span>${icon('pin')} ${esc(state.zone)}</span></div><div class="sum-row"><span>الإجمالي</span><span class="sum-total">${fmt(p.price)}</span></div></div><div class="panel"><label style="display:flex;gap:11px;align-items:center"><input id="acceptTerms" type="checkbox" style="width:19px;height:19px" ${state.acceptTerms?'checked':''}> <span>قرأت سياسة الاشتراك وأوافق على الشروط</span></label><p class="muted">التعديل والتأجيل يخضعان لمواعيد اعتماد المطعم. يبدأ الاشتراك بعد تأكيد الدفع.</p>${act('الانتقال إلى الدفع','subscription-confirm','primary','class="btn btn-primary btn-full"')}</div></div></div>`,'details');}
function payment(){const isSub=state.authContext==='subscription',total=isSub?plan().price:state.cart.reduce((v,x)=>v+(m(x.id)?.price||0)*x.qty,0);return pageWrap('اختيار طريقة الدفع','اختر الطريقة المناسبة لإكمال طلبك.',`<div class="split"><div class="stack"><div class="panel"><h3>طرق الدفع</h3><div class="checkout-choices"><button class="choice ${state.method==='cliq'?'selected':''}" data-action="payment-method:cliq"><b>تحويل CliQ</b><div class="muted">تحويل بنكي إلى 93 Kitchen</div></button><button class="choice ${state.method==='restaurant'?'selected':''}" data-action="payment-method:restaurant"><b>الدفع داخل المطعم</b><div class="muted">رقم مرجعي ورمز QR</div></button></div>${state.method==='cliq'?`<div class="panel" style="margin-top:15px;background:#f9fbf8"><h3>تفاصيل التحويل</h3><div class="sum-row"><span>اسم الاشتراك / المستفيد</span><b>93 Kitchen</b></div><p class="muted">بيانات الحساب البنكي المعتمدة تُعرض بعد ربط إعدادات الدفع.</p>${field('transferRef','رقم مرجع التحويل','text',false,'','رقم التحويل')}${act('إرسال إشعار التحويل','pay-submit','primary','class="btn btn-primary btn-full"')}</div>`:''}${state.method==='restaurant'?`<div class="panel" style="margin-top:15px;text-align:center"><h3>الدفع داخل المطعم</h3><img class="qr" src="assets/reference-qr.png" alt="رمز مرجعي للدفع داخل المطعم"><p><b>${esc(state.ref)}</b></p><p class="muted">أظهر هذا الرقم أو رمز QR عند الكاشير لإكمال الدفع.</p>${act('حفظ الطلب','pay-submit','primary','class="btn btn-primary btn-full"')}</div>`:''}</div></div><div class="panel"><h3>ملخص ${isSub?'الاشتراك':'الطلب'}</h3>${isSub?`<div class="sum-row"><span>الباقة</span><b>${esc(plan().name)}</b></div><div class="sum-row"><span>الوجبات</span><b>${plan().count}</b></div>`:state.cart.map(x=>`<div class="sum-row"><span>${esc(m(x.id)?.name)} × ${x.qty}</span><b>${fmt(m(x.id)?.price*x.qty)}</b></div>`).join('')}<div class="sum-row"><span>الاسم</span><b>${esc(state.details.name)}</b></div><div class="sum-row"><span>التوصيل</span><span>${icon('pin')} ${esc(state.zone)}</span></div><div class="sum-row"><span>الإجمالي</span><span class="sum-total">${fmt(total)}</span></div><p class="muted">يبدأ الاشتراك بعد تأكيد استلام الدفع.</p></div></div>`,'review');}
function paymentSuccess(){return pageWrap('تم الاشتراك بنجاح','اشتراكك أصبح فعالاً بعد تأكيد استلام الدفع.', '<section class="panel narrow center success-panel"><div class="success-icon">'+icon('check',32)+'</div><h2>تم الاشتراك بنجاح</h2><p>يمكنك الآن مراجعة وجباتك وجدول اشتراكك من حسابك.</p><div class="sum-row"><span>الاشتراك</span><b>'+esc(plan().name)+'</b></div><div class="sum-row"><span>المنطقة</span><b>'+esc(state.zone||'—')+'</b></div><div class="modal-actions">'+act('العودة إلى الرئيسية','navigate:home','secondary')+act('مراجعة اشتراكي','navigate:account','primary')+'</div></section>','home');}
function paymentPending(){let isSub=state.authContext==='subscription';return pageWrap('تم استلام طلبك','يمكنك الرجوع إلى حسابك لمتابعة الحالة.',`<div class="panel narrow center"><div style="font-size:48px;color:var(--green)">✓</div><h2 style="color:var(--green)">${isSub?'اشتراكك بانتظار تأكيد الدفع':'طلبك بانتظار تأكيد الدفع'}</h2><p class="muted">سيتم تفعيل ${isSub?'اشتراكك':'طلبك'} بعد التحقق من استلام الدفعة.</p><div class="sum-row"><span>الرقم المرجعي</span><b>${esc(state.ref)}</b></div><div class="sum-row"><span>طريقة الدفع</span><b>${state.method==='cliq'?'CliQ':'داخل المطعم'}</b></div><div class="modal-actions">${act('الرئيسية','navigate:home','secondary')}${act(isSub?'اشتراكي':'طلباتي',`navigate:${isSub?'account':'orders'}`,'primary')}</div></div>`,'home');}
function ordersPage(){const rows=state.orders.length?state.orders:[];return pageWrap('طلباتي','تابع طلباتك السابقة والحالية.',`<div class="panel"><h3>سجل الطلبات</h3>${rows.length?rows.map(x=>`<div class="sum-row"><div><b>${esc(x.ref)}</b><div class="muted">${esc(x.date)} · ${esc(x.items)}</div></div><span class="badge">${esc(x.status)}</span></div>`).join(''):'<div class="empty">ما عندك طلبات مسجلة بعد.</div>'}</div>`,'account');}
function accountPage(){if(!state.user){state.authContext='subscription';return authPage(false)}const ss=state.subscriptions;return pageWrap('أهلاً '+state.user.name.split(' ')[0]+'،','تابع اشتراكاتك وطلباتك ومعلومات حسابك.',`<div class="split"><div class="stack"><div class="panel"><h3>اشتراكاتي</h3>${ss.length?ss.map(s=>`<div class="sum-row"><div><b>${esc(s.plan)}</b><div class="muted">${esc(s.date)} · ${esc(s.ref)}</div></div><span class="badge">${esc(s.status)}</span></div>`).join(''):'<div class="empty">ما عندك اشتراك حالياً.</div>'}<div style="margin-top:15px">${act('استكشف الاشتراكات','navigate:plans','secondary')}</div></div><div class="panel"><h3>طلباتي</h3><p class="muted">شوف طلباتك وتابع حالتها.</p>${act('عرض الطلبات','navigate:orders','secondary')}</div></div><div class="panel"><h3>ملفي</h3><div class="sum-row"><span>الاسم</span><b>${esc(state.user.name)}</b></div><div class="sum-row"><span>البريد</span><span>${esc(state.user.email||'—')}</span></div><div class="sum-row"><span>المنطقة</span><span>${icon('pin')} ${esc(state.zone||'—')}</span></div>${act('تسجيل الخروج','logout','secondary')}</div></div>`,'home');}
function termsPage(){return pageWrap('سياسة الاشتراك والشروط','',`<div class="panel narrow"><h3>إدارة الاشتراك</h3><p>يمكنك اختيار الوجبات أسبوعياً وتقديم طلب لتعديلها أو تأجيلها بحسب مواعيد وشروط المطعم المعتمدة.</p><h3>إلغاء الاشتراك والاسترجاع</h3><p>تُراجع طلبات الإلغاء والاسترجاع حسب سياسة المطعم التي ستُنشر عند اعتمادها.</p><h3>بدء الاشتراك</h3><p>يبدأ الاشتراك بعد تأكيد استلام المبلغ.</p></div>`,'home');}
function aboutPage(){return pageWrap('عن مطبخنا','وجبات طازجة متوازنة بطابع بيتي.',`<div class="about"><div class="about-text"><h2>مطبخنا</h2><p>في 93 Kitchen بنحضّر وجبات بعناية لتناسب يومك، سواء طلب واحد أو اشتراك موزّع على الأسبوع.</p>${act('تصفح المنيو','navigate:menu','primary')}</div><img class="about-image" src="assets/chef.webp" alt="طعام مطهو حديثاً"></div>`,'home');}
function locationModal(){if(!state.modal||state.modal!=='location')return '';const covered=state.gov==='عمّان'&&state.zone;return `<div class="modal-scrim" data-action="modal-close"></div><div class="modal-wrap"><div class="modal-box"><div class="panel-title"><h2>حدد منطقتك</h2><button class="icon-btn" data-action="modal-close" aria-label="إغلاق">${icon('close')}</button></div><p class="muted">خلينا نتأكد إذا منطقة التوصيل مشمولة قبل ما نكمل.</p><div class="modal-grid">${areaField()}${state.gov&&state.gov!=='عمّان'?'<div class="warning">التوصيل لهذه المحافظة بحاجة تأكيد من المطعم.</div>':''}${state.gov==='عمّان'&&state.zone?'<div class="success">تم تحديد منطقتك. التغطية النهائية تعتمد على تأكيد المطعم.</div>':''}</div><div class="modal-actions">${act('إلغاء','modal-close','secondary')}${act('تحقّق من التوصيل','verify-location','primary',''+(!covered?'disabled':''))}</div></div></div>`;}
function mealSelectModal(){if(state.modal!=='meal-select')return '';const target=state.editDay??0,eligible=plan().id==='chicken'?MEALS.filter(x=>x.cat==='دجاج'):MEALS.filter(x=>!['فطور','سلطات'].includes(x.cat));return `<div class="modal-scrim" data-action="modal-close"></div><div class="modal-wrap"><div class="modal-box"><div class="panel-title"><h2>اختار وجبتك</h2><button class="icon-btn" data-action="modal-close" aria-label="إغلاق">${icon('close')}</button></div><div class="modal-grid">${eligible.map(x=>`<button class="choice" style="width:100%" data-action="daychoose:${target}:${x.id}"><b>${esc(x.name)}</b><span class="muted">${fmt(x.price)}</span></button>`).join('')}</div></div></div>`;}
function toast(msg){state.toast=msg;clearTimeout(popTimer);popTimer=setTimeout(()=>{state.toast='';render()},3500);render()}
function staffLogin(){return '<main class="staff-login-layout"><aside class="staff-login-brand"><img src="assets/logo.svg" alt="93 Kitchen"><div><h2>لوحة إدارة المطعم</h2><p>تابع الطلبات والاشتراكات والمنيو والعملاء والمالية من مكان واحد.</p><small>مطبخ منظم · خدمة أفضل</small></div></aside><section class="staff-login-content"><div class="staff-login-inner"><button class="back" data-action="navigate:home">العودة إلى موقع الزبائن</button><h1>تسجيل دخول الموظفين</h1><p class="muted">أدخل الرقم الوظيفي وكلمة المرور للمتابعة إلى لوحة الإدارة.</p><form id="staffForm" class="stack">'+field('staffId','الرقم الوظيفي','text',true,'','الرقم الوظيفي')+field('staffPass','كلمة المرور','password',true,'','كلمة المرور')+act('تسجيل الدخول','staff-submit','primary','type="submit" class="btn btn-primary btn-full"')+'</form><p class="muted staff-login-note">إنشاء حسابات الموظفين وتحديد الصلاحيات يتم بواسطة المسؤول المباشر.</p></div></section></main>';}
